"""A stationary, six-project homepage using the existing portfolio records."""
from html import escape as e
from pathlib import Path
import hashlib,json

def render_home(projects,head,header,footer):
 root=Path(__file__).parent/'dist'
 version=lambda f:hashlib.sha256((root/f).read_bytes()).hexdigest()[:10]
 # Keep the requested showcase sequence; the records themselves are never rewritten.
 records={p['slug']:p for p in projects}
 featured=[records[s] for s in ['husky','mattermost','lockheed-martin','leidos-cld','zales','leidos-animation']]
 for record in featured:
  record['format']={'husky':'Digital experience','mattermost':'Interactive web','lockheed-martin':'Dual-screen experience','leidos-cld':'Website','zales':'WebXR experience','leidos-animation':'Animation'}[record['slug']]
 p=featured[0]
 page=head('Selected Work / Ben Diaz','Six selected projects in UI/UX, interactive experiences, WebXR, and motion design.','home-editorial')
 page=page.replace('</head>',f'<link rel="stylesheet" href="/homepage.css?v={version("homepage.css")}"><script defer src="/project-gesture.js?v={version("project-gesture.js")}"></script><script defer src="/homepage.js?v={version("homepage.js")}"></script></head>')+header()
 page+='''<section class="home-introduction" aria-labelledby="intro-title"><div class="intro-portrait" aria-hidden="true"></div><div class="intro-copy"><span class="micro">HELLO, I’M BEN DIAZ</span><h1 id="intro-title" tabindex="-1">Designer.<br>Then everything<br><em>else.</em></h1><div class="intro-bottom"><p>I’m a UX/UI designer working across interfaces, immersive experiences, websites, WebXR, and motion. I connect clear ideas with experiences that feel alive.</p><a href="/about/" class="intro-work micro">MORE ABOUT ME <span aria-hidden="true">→</span></a></div></div><span class="intro-aside micro">INTERFACES / EXPERIENCES / MOTION</span></section>'''
 page+='''<main id="main" class="project-stage" aria-label="Selected work"><div class="project-backdrops" aria-hidden="true"><img class="project-backdrop is-front" src="/assets/projects-husky.jpg" alt=""><img class="project-backdrop" alt=""></div><button type="button" class="showcase-top micro" aria-label="Back to top">↑ <span>BACK TO TOP</span></button><section class="project-information" aria-labelledby="selected-work"><div class="project-copy" aria-live="polite" aria-atomic="true"><span class="project-count micro"><span data-current>01</span><span class="count-divider">/</span>06</span>'''
 page+=f'''<div class="company-heading"><h1 id="selected-work" data-title>{e(p['client'])}</h1><p class="project-category micro" data-category>{e(p['short'])}</p></div><p class="project-description" data-description>{e(p['description'])}</p><div class="project-details"><div><span class="micro">MY ROLE</span><p class="project-role" data-role>{e(p['role'])}</p><span class="micro">RESPONSIBILITIES</span><p data-responsibilities>{e(p['responsibilities'])}</p></div><div><span class="micro">CLIENT</span><p data-client>{e(p['client'])}</p><span class="micro">FORMAT</span><p data-format>{e(p['format'])}</p></div></div></div><a class="explore-project micro" data-project-link href="/work/{p['slug']}/"><span class="outline-arrow" aria-hidden="true">↗</span>EXPLORE PROJECT</a></section><section class="project-presentation" aria-label="Featured project"><a class="featured-project" data-project-link href="/work/{p['slug']}/" aria-label="View {e(p['client'])} case study"><div class="project-visual"><div class="image-depth"><img class="project-image is-front" src="/assets/{p['image']}" alt="{e(p['alt'])}" fetchpriority="high" decoding="async"><img class="project-image" alt="" aria-hidden="true" decoding="async"></div></div><div class="project-shade" aria-hidden="true"></div><div class="card-topline micro"><span data-card-number>01 / 06</span></div><div class="card-lockup"><div><span class="card-stroke" aria-hidden="true"></span><h2 data-card-title>{e(p['client'])}</h2><span class="card-category micro" data-card-category>{e(p['kind'])}</span></div><span class="card-cta micro">VIEW PROJECT<span aria-hidden="true">↗</span></span></div></a></section>'''
 page+='''<nav class="project-navigator" aria-label="Project navigator. Scroll or use up and down arrow keys."><div class="number-track"><span class="nav-glider" aria-hidden="true"></span>'''
 for i,p in enumerate(featured):
  page+=f'<button type="button" data-select="{i}" aria-label="Select {i+1:02d}: {e(p["client"])}" aria-pressed="{str(i==0).lower()}"><span class="nav-name" aria-hidden="true">{e(p["client"])}</span><span class="nav-tick" aria-hidden="true"></span><span class="nav-number">{i+1:02d}</span></button>'
 page+='''</div></nav><div class="stage-bottom micro"><div class="browse-controls project-arrows" role="group" aria-label="Browse projects"><button type="button" aria-label="Previous project">↑</button><span class="browse-instruction">SCROLL TO EXPLORE</span><button type="button" aria-label="Next project">↓</button></div><a href="/work/">ALL PROJECTS <svg class="all-projects-arrow" viewBox="0 0 24 16" fill="none" stroke="currentColor" stroke-width="1.2" aria-hidden="true"><path d="M1 8h21m-6-6 6 6-6 6"/></svg></a></div></main>'''
 page+='<script type="application/json" id="project-records">'+json.dumps(featured).replace('<','\\u003c')+'</script>'+footer().replace('<span>MIDWEST BORN &amp; BRED</span>','')
 return page
